-- Phase 21 — évaluations, notes, compétences et règles de calcul
CREATE TYPE "academic_period_status" AS ENUM ('DRAFT', 'OPEN', 'CLOSED');
CREATE TYPE "assessment_status" AS ENUM ('DRAFT', 'PUBLISHED', 'LOCKED');
CREATE TYPE "grading_weighting_mode" AS ENUM ('WEIGHTED_AVERAGE', 'POINTS_TOTAL');

CREATE TABLE "academic_periods" ("id" UUID NOT NULL DEFAULT uuidv7(), "school_id" UUID NOT NULL, "academic_year_id" UUID NOT NULL, "name" TEXT NOT NULL, "order_index" INTEGER NOT NULL, "start_date" DATE NOT NULL, "end_date" DATE NOT NULL, "status" "academic_period_status" NOT NULL DEFAULT 'DRAFT', "created_at" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" TIMESTAMPTZ(3) NOT NULL, CONSTRAINT "academic_periods_pkey" PRIMARY KEY ("id"), CONSTRAINT "academic_periods_dates_valid" CHECK (end_date >= start_date), CONSTRAINT "academic_periods_school_id_fkey" FOREIGN KEY ("school_id") REFERENCES "schools"("id") ON DELETE CASCADE, CONSTRAINT "academic_periods_academic_year_id_fkey" FOREIGN KEY ("academic_year_id") REFERENCES "academic_years"("id") ON DELETE CASCADE);
CREATE TABLE "assessment_types" ("id" UUID NOT NULL DEFAULT uuidv7(), "school_id" UUID NOT NULL, "code" TEXT NOT NULL, "name" TEXT NOT NULL, "default_weight" INTEGER NOT NULL, "status" "reference_status" NOT NULL DEFAULT 'ACTIVE', "created_at" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" TIMESTAMPTZ(3) NOT NULL, CONSTRAINT "assessment_types_pkey" PRIMARY KEY ("id"), CONSTRAINT "assessment_types_weight_positive" CHECK (default_weight > 0), CONSTRAINT "assessment_types_school_id_fkey" FOREIGN KEY ("school_id") REFERENCES "schools"("id") ON DELETE CASCADE);
CREATE TABLE "competencies" ("id" UUID NOT NULL DEFAULT uuidv7(), "school_id" UUID NOT NULL, "code" TEXT NOT NULL, "name" TEXT NOT NULL, "description" TEXT, "status" "reference_status" NOT NULL DEFAULT 'ACTIVE', "created_at" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" TIMESTAMPTZ(3) NOT NULL, CONSTRAINT "competencies_pkey" PRIMARY KEY ("id"), CONSTRAINT "competencies_school_id_fkey" FOREIGN KEY ("school_id") REFERENCES "schools"("id") ON DELETE CASCADE);
CREATE TABLE "grading_policies" ("id" UUID NOT NULL DEFAULT uuidv7(), "school_id" UUID NOT NULL, "academic_year_id" UUID NOT NULL, "cycle" "education_cycle", "version" INTEGER NOT NULL, "rounding_digits" INTEGER NOT NULL DEFAULT 2, "weighting_mode" "grading_weighting_mode" NOT NULL DEFAULT 'WEIGHTED_AVERAGE', "is_active" BOOLEAN NOT NULL DEFAULT true, "created_at" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "grading_policies_pkey" PRIMARY KEY ("id"), CONSTRAINT "grading_policies_values_valid" CHECK (version > 0 AND rounding_digits BETWEEN 0 AND 2), CONSTRAINT "grading_policies_school_id_fkey" FOREIGN KEY ("school_id") REFERENCES "schools"("id") ON DELETE CASCADE, CONSTRAINT "grading_policies_academic_year_id_fkey" FOREIGN KEY ("academic_year_id") REFERENCES "academic_years"("id") ON DELETE CASCADE);
CREATE TABLE "assessments" ("id" UUID NOT NULL DEFAULT uuidv7(), "school_id" UUID NOT NULL, "academic_year_id" UUID NOT NULL, "period_id" UUID NOT NULL, "teaching_assignment_id" UUID NOT NULL, "class_id" UUID NOT NULL, "type_id" UUID NOT NULL, "title" TEXT NOT NULL, "date" DATE NOT NULL, "max_score" INTEGER NOT NULL, "weight" INTEGER NOT NULL, "status" "assessment_status" NOT NULL DEFAULT 'DRAFT', "published_at" TIMESTAMPTZ(3), "created_at" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" TIMESTAMPTZ(3) NOT NULL, CONSTRAINT "assessments_pkey" PRIMARY KEY ("id"), CONSTRAINT "assessments_values_positive" CHECK (max_score > 0 AND weight > 0), CONSTRAINT "assessments_school_id_fkey" FOREIGN KEY ("school_id") REFERENCES "schools"("id") ON DELETE CASCADE, CONSTRAINT "assessments_academic_year_id_fkey" FOREIGN KEY ("academic_year_id") REFERENCES "academic_years"("id") ON DELETE CASCADE, CONSTRAINT "assessments_period_id_fkey" FOREIGN KEY ("period_id") REFERENCES "academic_periods"("id") ON DELETE RESTRICT, CONSTRAINT "assessments_teaching_assignment_id_fkey" FOREIGN KEY ("teaching_assignment_id") REFERENCES "teaching_assignments"("id") ON DELETE RESTRICT, CONSTRAINT "assessments_class_id_fkey" FOREIGN KEY ("class_id") REFERENCES "classes"("id") ON DELETE RESTRICT, CONSTRAINT "assessments_type_id_fkey" FOREIGN KEY ("type_id") REFERENCES "assessment_types"("id") ON DELETE RESTRICT);
CREATE TABLE "assessment_competencies" ("assessment_id" UUID NOT NULL, "competency_id" UUID NOT NULL, CONSTRAINT "assessment_competencies_pkey" PRIMARY KEY ("assessment_id", "competency_id"), CONSTRAINT "assessment_competencies_assessment_id_fkey" FOREIGN KEY ("assessment_id") REFERENCES "assessments"("id") ON DELETE CASCADE, CONSTRAINT "assessment_competencies_competency_id_fkey" FOREIGN KEY ("competency_id") REFERENCES "competencies"("id") ON DELETE RESTRICT);
CREATE TABLE "grades" ("id" UUID NOT NULL DEFAULT uuidv7(), "school_id" UUID NOT NULL, "assessment_id" UUID NOT NULL, "enrollment_id" UUID NOT NULL, "score" INTEGER, "is_absent" BOOLEAN NOT NULL DEFAULT false, "comment" TEXT, "created_at" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" TIMESTAMPTZ(3) NOT NULL, CONSTRAINT "grades_pkey" PRIMARY KEY ("id"), CONSTRAINT "grades_score_nonnegative" CHECK (score IS NULL OR score >= 0), CONSTRAINT "grades_school_id_fkey" FOREIGN KEY ("school_id") REFERENCES "schools"("id") ON DELETE CASCADE, CONSTRAINT "grades_assessment_id_fkey" FOREIGN KEY ("assessment_id") REFERENCES "assessments"("id") ON DELETE CASCADE, CONSTRAINT "grades_enrollment_id_fkey" FOREIGN KEY ("enrollment_id") REFERENCES "enrollments"("id") ON DELETE RESTRICT);

CREATE UNIQUE INDEX "academic_periods_academic_year_id_order_index_key" ON "academic_periods"("academic_year_id", "order_index"); CREATE UNIQUE INDEX "academic_periods_academic_year_id_name_key" ON "academic_periods"("academic_year_id", "name"); CREATE INDEX "academic_periods_school_id_academic_year_id_status_idx" ON "academic_periods"("school_id", "academic_year_id", "status");
CREATE UNIQUE INDEX "assessment_types_school_id_code_key" ON "assessment_types"("school_id", "code"); CREATE INDEX "assessment_types_school_id_status_idx" ON "assessment_types"("school_id", "status");
CREATE UNIQUE INDEX "competencies_school_id_code_key" ON "competencies"("school_id", "code"); CREATE INDEX "competencies_school_id_status_idx" ON "competencies"("school_id", "status");
CREATE UNIQUE INDEX "grading_policies_academic_year_id_cycle_version_key" ON "grading_policies"("academic_year_id", "cycle", "version"); CREATE INDEX "grading_policies_school_id_academic_year_id_is_active_idx" ON "grading_policies"("school_id", "academic_year_id", "is_active");
CREATE INDEX "assessments_school_id_academic_year_id_period_id_status_idx" ON "assessments"("school_id", "academic_year_id", "period_id", "status"); CREATE INDEX "assessments_class_id_date_idx" ON "assessments"("class_id", "date"); CREATE INDEX "assessments_teaching_assignment_id_period_id_idx" ON "assessments"("teaching_assignment_id", "period_id"); CREATE INDEX "assessment_competencies_competency_id_idx" ON "assessment_competencies"("competency_id");
CREATE UNIQUE INDEX "grades_assessment_id_enrollment_id_key" ON "grades"("assessment_id", "enrollment_id"); CREATE INDEX "grades_school_id_enrollment_id_created_at_idx" ON "grades"("school_id", "enrollment_id", "created_at" DESC);

DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['academic_periods','assessment_types','competencies','assessments','grades'] LOOP EXECUTE format('CREATE TRIGGER trg_%1$s_updated_at BEFORE UPDATE ON %1$I FOR EACH ROW EXECUTE FUNCTION set_updated_at()', t); END LOOP; FOREACH t IN ARRAY ARRAY['academic_periods','assessment_types','competencies','grading_policies','assessments','grades'] LOOP EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY', t); EXECUTE format('CREATE POLICY school_isolation ON %I USING (current_school_id() IS NULL OR school_id = current_school_id()) WITH CHECK (current_school_id() IS NULL OR school_id = current_school_id())', t); END LOOP; END $$;
